/* @autogenerated */
import { rootLogger } from '@shared/context/observability/logger.service';
import {
  computed,
  DestroyRef,
  inject,
  Injectable,
  Injector,
  isSignal,
  linkedSignal,
  Signal,
  signal,
  untracked,
  WritableSignal,
} from '@angular/core';
import { toObservable } from '@angular/core/rxjs-interop';
import { Observable } from 'rxjs';
import { ANONYMOUS_USER, UserInfo } from '../identity/user-info.model';
import { DefaultsService } from '../config/defaults.service';

/** Clave de una entrada del contexto (tenant, organización…): la define cada selector de contexto. */
export type ContextKey = string;

/** @deprecated Usa los signals de `AppStateService` o sus observables `*$`. Se eliminará en la próxima versión. */
export interface AppStateItem<T> extends Observable<T> {
  set: (value: T) => void;
}

/** Canal compartido por las pestañas y los micro-frontends del mismo origen. */
export const APP_STATE_CHANNEL = 'app-state';

/** Lo que se propaga a las demás pestañas y micro-frontends. */
export type AppStateMessage =
  | { readonly type: 'language'; readonly value: string }
  | { readonly type: 'tenant'; readonly value: string }
  | { readonly type: 'logout'; readonly identity: string };

const STORAGE_PREFIX = 'state-item-';

@Injectable({
  providedIn: 'root',
})
export class AppStateService {
  private readonly defaults = inject(DefaultsService);
  private readonly injector = inject(Injector);
  private readonly channel = openChannel();
  // Mientras se aplica un mensaje recibido no se vuelve a publicar: evita el eco entre pestañas
  private applyingRemote = false;

  /** Idioma elegido por el usuario o, si no ha elegido, el de `DefaultsService`. */
  public readonly language = persistedSignal('selected-language', this.defaults.language, (value) =>
    this.publish({ type: 'language', value }),
  );
  /** Tenant elegido por el usuario o, si no ha elegido, el de `DefaultsService`. */
  public readonly tenant = persistedSignal('selected-tenant', this.defaults.tenant, (value) =>
    this.publish({ type: 'tenant', value }),
  );
  public readonly language$ = toObservable(this.language);
  public readonly tenant$ = toObservable(this.tenant);

  private readonly usersState = signal<Record<string, UserInfo>>({});
  /** Usuario de cada identidad; las identidades sin usuario no aparecen. */
  public readonly users = this.usersState.asReadonly();

  private readonly contextState = persistedSignal<Record<ContextKey, ContextValue | null>>(
    'context',
    {},
    undefined,
    reviveContext,
  );
  public readonly contexts = this.contextState.asReadonly();

  /** Valores del contexto que se inyectan en el body de las mutaciones. */
  public readonly fixedValues = computed(() => pickValues(this.contexts(), (ctx) => ctx.fixed && !!ctx.value));
  /** Valores del contexto que se envían como filtro en las peticiones. */
  public readonly filterValues = computed(() => pickValues(this.contexts(), (ctx) => ctx.toFilter));

  private readonly fixedValues$ = toObservable(this.fixedValues);
  private readonly filterValues$ = toObservable(this.filterValues);

  private readonly userSignals = new Map<string, Signal<UserInfo>>();
  private readonly userStreams = new Map<string, Observable<UserInfo>>();
  private readonly contextSignals = new Map<ContextKey, Signal<ContextValue | null>>();
  private readonly contextStreams = new Map<ContextKey, Observable<ContextValue | null>>();

  /** @deprecated Usa `user(key)`, `user$(key)` y `setUser(key, user)`. Se eliminará en la próxima versión. */
  public readonly userInfo = legacyIndex<UserInfo>(
    (key) => this.user$(key),
    (key, value) => this.setUser(key, value),
  );
  /** @deprecated Usa `contextValue(key)`, `context$(key)` y `setContext(key, value)`. Se eliminará en la próxima versión. */
  public readonly context = legacyIndex<ContextValue | null>(
    (key) => this.context$(key),
    (key, value) => this.setContext(key, value),
  );

  constructor() {
    if (this.channel) {
      const channel = this.channel;
      const listener = (event: MessageEvent<unknown>) => this.receive(event.data);
      channel.addEventListener('message', listener);
      inject(DestroyRef).onDestroy(() => {
        channel.removeEventListener('message', listener);
        channel.close();
      });
    }
  }

  /** Usuario de la identidad `key`; anónimo mientras no haya uno. Leerlo no crea estado. */
  public user(key: string): Signal<UserInfo> {
    return cached(this.userSignals, key, () => computed(() => this.users()[key] ?? ANONYMOUS_USER));
  }

  public user$(key: string): Observable<UserInfo> {
    return cached(this.userStreams, key, () => toObservable(this.user(key), { injector: this.injector }));
  }

  public setUser(key: string, user: UserInfo): void {
    const previous = untracked(this.user(key));
    this.usersState.update((users) => ({ ...users, [key]: user }));
    if (previous.authenticated && !user.authenticated) {
      this.publish({ type: 'logout', identity: key });
    }
  }

  /** Entrada `key` del contexto; null mientras no tenga valor. Leerla no crea estado. */
  public contextValue(key: ContextKey): Signal<ContextValue | null> {
    return cached(this.contextSignals, key, () => computed(() => this.contexts()[key] ?? null));
  }

  public context$(key: ContextKey): Observable<ContextValue | null> {
    return cached(this.contextStreams, key, () => toObservable(this.contextValue(key), { injector: this.injector }));
  }

  public setContext(key: ContextKey, value: ContextValue | null): void {
    this.contextState.update((contexts) => ({ ...contexts, [key]: value }));
  }

  public fixedContext(): Observable<Record<ContextKey, unknown>> {
    return this.fixedValues$;
  }

  public filterContext(): Observable<Record<ContextKey, unknown>> {
    return this.filterValues$;
  }

  private publish(message: AppStateMessage): void {
    if (!this.applyingRemote) {
      this.channel?.postMessage(message);
    }
  }

  private receive(data: unknown): void {
    if (!isMessage(data)) {
      return;
    }
    this.applyingRemote = true;
    try {
      if (data.type === 'language') {
        this.language.set(data.value);
      } else if (data.type === 'tenant') {
        this.tenant.set(data.value);
      } else if (untracked(this.user(data.identity)).authenticated) {
        this.setUser(data.identity, ANONYMOUS_USER);
      }
    } finally {
      this.applyingRemote = false;
    }
  }
}

export class ContextValue {
  private constructor(
    public readonly label: string,
    public readonly value: any,
    public readonly fixed: boolean,
    public readonly toFilter: boolean,
  ) {}

  public static null(label: string) {
    return new ContextValue(label, null, true, false);
  }

  public static default(label: string, value: any) {
    return new ContextValue(label, value, true, false);
  }

  public static fixed(label: string, value: any) {
    return new ContextValue(label, value, true, true);
  }

  public static filter(label: string, value: any) {
    return new ContextValue(label, value, false, true);
  }

  public static selection(label: string, value: any) {
    return new ContextValue(label, value, false, false);
  }

  /** Reconstruye un valor leído de `localStorage`; null si no tiene la forma esperada. */
  public static restore(raw: unknown): ContextValue | null {
    if (typeof raw !== 'object' || raw === null) {
      return null;
    }
    const { label, value, fixed, toFilter } = raw as Partial<ContextValue>;
    return typeof label === 'string' ? new ContextValue(label, value, !!fixed, !!toFilter) : null;
  }
}

/**
 * Signal guardado en `localStorage`. Mientras no se escriba sigue a `initial` (que puede ser un signal,
 * p. ej. el valor por defecto que llega con la configuración); al escribirlo se guarda y se avisa a `onChange`.
 */
export function persistedSignal<T>(
  key: string,
  initial: T | Signal<T>,
  onChange?: (value: T) => void,
  revive: (raw: unknown) => T = (raw) => raw as T,
): WritableSignal<T> {
  const storageKey = STORAGE_PREFIX + key;
  const fallback = isSignal(initial) ? initial : () => initial;
  // Si cambia el valor por defecto se vuelve a leer lo guardado: lo elegido por el usuario manda
  const state = linkedSignal<T>(() => {
    const stored = readStored(storageKey);
    return stored === undefined ? fallback() : revive(stored);
  });
  const write = state.set;
  state.set = (value: T) => {
    if (Object.is(untracked(state), value)) {
      return;
    }
    write(value);
    writeStored(storageKey, value);
    onChange?.(value);
  };
  state.update = (fn: (value: T) => T) => state.set(fn(untracked(state)));
  return state;
}

function readStored(storageKey: string): unknown {
  try {
    const stored = localStorage.getItem(storageKey);
    return stored === null ? undefined : (JSON.parse(stored)?.data ?? undefined);
  } catch {
    rootLogger.warn(`Ignoring unreadable state item ${storageKey}`);
    return undefined;
  }
}

function writeStored(storageKey: string, value: unknown): void {
  try {
    localStorage.setItem(storageKey, JSON.stringify({ data: value }));
  } catch {
    // Sin cuota o en modo privado: el estado sigue en memoria
    rootLogger.warn(`Unable to persist state item ${storageKey}`);
  }
}

function reviveContext(raw: unknown): Record<ContextKey, ContextValue | null> {
  if (typeof raw !== 'object' || raw === null) {
    return {};
  }
  return Object.fromEntries(Object.entries(raw).map(([key, value]) => [key, ContextValue.restore(value)]));
}

function pickValues(
  contexts: Record<ContextKey, ContextValue | null>,
  accept: (ctx: ContextValue) => boolean,
): Record<ContextKey, unknown> {
  const result: Record<ContextKey, unknown> = {};
  Object.entries(contexts).forEach(([key, ctx]) => {
    if (ctx && accept(ctx)) {
      result[key] = ctx.value;
    }
  });
  return result;
}

function cached<K, V>(cache: Map<K, V>, key: K, build: () => V): V {
  let value = cache.get(key);
  if (value === undefined) {
    value = build();
    cache.set(key, value);
  }
  return value;
}

function openChannel(): BroadcastChannel | null {
  return typeof BroadcastChannel === 'undefined' ? null : new BroadcastChannel(APP_STATE_CHANNEL);
}

function isMessage(data: unknown): data is AppStateMessage {
  if (typeof data !== 'object' || data === null) {
    return false;
  }
  const message = data as Partial<Record<'type' | 'value' | 'identity', unknown>>;
  return (
    ((message.type === 'language' || message.type === 'tenant') && typeof message.value === 'string') ||
    (message.type === 'logout' && typeof message.identity === 'string')
  );
}

class LegacyStateItem<T> extends Observable<T> implements AppStateItem<T> {
  constructor(
    source: Observable<T>,
    private readonly write: (value: T) => void,
  ) {
    super((subscriber) => source.subscribe(subscriber));
  }

  set(value: T): void {
    this.write(value);
  }
}

function legacyIndex<T>(
  read: (key: string) => Observable<T>,
  write: (key: string, value: T) => void,
): Readonly<Record<string, AppStateItem<T>>> {
  const items = new Map<string, AppStateItem<T>>();
  return new Proxy<Record<string, AppStateItem<T>>>(
    {},
    {
      get: (_target, prop) =>
        typeof prop === 'string'
          ? cached(items, prop, () => new LegacyStateItem<T>(read(prop), (value) => write(prop, value)))
          : undefined,
    },
  );
}
